mapper.select:
select
from knowledge_base where status = 'ACTIVE' and deleted_at is null and id in
#{id}

select
from knowledge_base
order by updated_at desc, id desc limit #{limit} offset #{offset}

mapper.update:
update knowledge_base kb join ( select kb_id, count(1) as document_count, coalesce(sum(segment_count), 0) as segment_count from asset where kb_id = #{id} and deleted_at is null group by kb_id ) s on kb.id = s.kb_id set kb.document_count = s.document_count, kb.segment_count = s.segment_count, kb.updated_by = #{updatedBy}, kb.updated_at = #{updatedAt}
, kb.last_ingested_at = #{lastIngestedAt}
where kb.id = #{id} and kb.deleted_at is null
